#include <stdio.h>
#include <string.h>

int main() {
    const char *words[] = {"racecar", "banana", "noon", "abca"};
    for (int w = 0; w < 4; w++) {
        const char *s = words[w];
        int ok = 1;
        for (int i = 0, j = strlen(s) - 1; i < j; i++, j--) {
            if (s[i] != s[j]) {
                ok = 0;
            }
        }
        printf("%s: %s\n", s, ok ? "yes" : "no");
    }
    return 0;
}
